import { describe, expect, it } from "vitest";
import {
  fingerprintLegalDescriptorV1,
  LEGAL_FINGERPRINT_MAX_ARRAY_ITEMS,
  LegalFingerprintV1Error,
} from "./legal-fingerprint-v1";

const ASCII_ROUTE = Object.freeze({
  schema_version: "ai_legal_route_identity_v1",
  route_descriptor_id: "route.deepseek.v1",
  profile_key: "deepseek.official.deepseek-v4-flash.chat.v1",
  gateway_kind: "direct_deepseek",
  operator_identity_status: "known",
  operator_legal_name: "Hangzhou DeepSeek Artificial Intelligence Co., Ltd.",
  model_vendor_id: "deepseek",
  model_vendor_name: "DeepSeek",
  model_id: "deepseek-v4-flash",
  wire_api_kind: "chat_completions_v1",
  endpoint_alias: "deepseek_official",
  canonical_endpoint_url: "https://api.deepseek.com/chat/completions",
  display_disclosure_key: "deepseek-official-v1",
});

// Generated by an independent PowerShell/.NET UTF-8 record builder and SHA256,
// not by fingerprintLegalDescriptorV1 or any production helper.
const ASCII_ROUTE_STREAM_HEX =
  "";
const ASCII_ROUTE_SHA256 = "cd9f9a0448d48443fb591d89254743c7e6cbfa3a9fc54a2ccc700efe7a8742c7";

const MULTIBYTE_FACT = Object.freeze({
  schema_version: "ai_legal_fact_v1",
  fact_id: "fact.multibyte.v1",
  category: "display",
  authority_class: "service-display",
  operational_scope: "",
  status: "confirmed",
  subject: "AI 条款",
  predicate: "uses reviewed label",
  object: "Café / 数据🔐",
  scope: "locale-neutral semantic meaning",
  qualifiers: ["中文", "Café"],
});

const MULTIBYTE_FACT_STREAM_HEX =
  "";
const MULTIBYTE_FACT_SHA256 = "297b52ff74ec77a049e1e4864f980f65fff636749287bb45e155cb9f5db79e47";

describe("legal fingerprint v1 canonicalizer", () => {
  it("matches the independent ASCII exact-byte and SHA-256 vector", () => {
    const result = fingerprintLegalDescriptorV1(ASCII_ROUTE);
    expect(result.bytes.toString("hex")).toBe(ASCII_ROUTE_STREAM_HEX);
    expect(result.sha256).toBe(ASCII_ROUTE_SHA256);
  });

  it("normalizes NFC, sorts a set by UTF-8 bytes, and matches the independent multibyte vector", () => {
    const result = fingerprintLegalDescriptorV1({
      ...MULTIBYTE_FACT,
      object: "Cafe\u0301 / 数据🔐",
      qualifiers: ["中文", "Cafe\u0301"],
    });
    expect(result.normalized.object).toBe("Café / 数据🔐");
    expect(result.normalized.qualifiers).toEqual(["Café", "中文"]);
    expect(result.bytes.toString("hex")).toBe(MULTIBYTE_FACT_STREAM_HEX);
    expect(result.sha256).toBe(MULTIBYTE_FACT_SHA256);
  });

  it.each(["\ud800", "\udc00", "text\ud800more"])(
    "rejects a lone surrogate before UTF-8 encoding (%j)",
    (object) => {
      expect(() => fingerprintLegalDescriptorV1({ ...MULTIBYTE_FACT, object })).toThrow(
        /lone UTF-16 surrogate/,
      );
    },
  );

  it("rejects NFC-equivalent duplicate set elements instead of silently deduplicating", () => {
    expect(() =>
      fingerprintLegalDescriptorV1({
        ...MULTIBYTE_FACT,
        qualifiers: ["Café", "Cafe\u0301"],
      }),
    ).toThrow(/NFC-duplicate/);
  });

  it("sorts ID/hash pairs together and rejects duplicate IDs", () => {
    const hashA = "a".repeat(64);
    const hashB = "b".repeat(64);
    const manifest = {
      schema_version: "ai_legal_manifest_fingerprint_v1",
      manifest_id: "manifest.v1",
      display_disclosure_key: "display.v1",
      reviewed_at: "2026-08-23@Asia/Shanghai",
      route_descriptor_ids: ["route.z", "route.a"],
      route_descriptor_sha256s: [hashB, hashA],
      subject_descriptor_id: "subject.v1",
      subject_descriptor_sha256: hashA,
      fact_ids: ["fact.z", "fact.a"],
      fact_sha256s: [hashB, hashA],
      evidence_ids: ["evidence.z", "evidence.a"],
      evidence_sha256s: [hashB, hashA],
    };
    const normalized = fingerprintLegalDescriptorV1(manifest).normalized;
    expect(normalized.route_descriptor_ids).toEqual(["route.a", "route.z"]);
    expect(normalized.route_descriptor_sha256s).toEqual([hashA, hashB]);
    expect(() =>
      fingerprintLegalDescriptorV1({
        ...manifest,
        fact_ids: ["fact.a", "fact.a"],
      }),
    ).toThrow(/equal length|duplicate pair ID/);
  });

  it.each([
    ["missing", Object.fromEntries(Object.entries(ASCII_ROUTE).filter(([key]) => key !== "model_id"))],
    ["unknown", { ...ASCII_ROUTE, surprise: "x" }],
    ["wrong scalar type", { ...ASCII_ROUTE, model_id: 42 }],
    ["wrong boolean type", {
      schema_version: "ai_legal_provider_subject_v1",
      subject_descriptor_id: "subject.none.v1",
      mode: "none",
      wire_field: "",
      algorithm: "",
      secret_class: "",
      derivation_message_schema: "",
      output_encoding: "",
      source_identity_class: "",
      raw_email_sent: "false",
      raw_username_sent: false,
      raw_account_id_sent: false,
      documented_purposes: [],
    }],
  ])("rejects a descriptor with %s fields", (_label, descriptor) => {
    expect(() => fingerprintLegalDescriptorV1(descriptor)).toThrow(LegalFingerprintV1Error);
  });

  it("enforces enum, conditional-empty, code-ID, SHA and date grammars", () => {
    expect(() => fingerprintLegalDescriptorV1({ ...ASCII_ROUTE, operator_identity_status: "maybe" })).toThrow(/enum/);
    expect(() => fingerprintLegalDescriptorV1({ ...ASCII_ROUTE, operator_identity_status: "unverified" })).toThrow(/operator_legal_name/);
    expect(() => fingerprintLegalDescriptorV1({ ...ASCII_ROUTE, route_descriptor_id: "é" })).toThrow(/ASCII code ID/);
    expect(() => fingerprintLegalDescriptorV1({
      schema_version: "ai_legal_manifest_fingerprint_v1",
      manifest_id: "manifest.v1", display_disclosure_key: "display.v1",
      reviewed_at: "2026-08-23T00:00:00Z",
      route_descriptor_ids: ["route.v1"], route_descriptor_sha256s: ["a".repeat(64)],
      subject_descriptor_id: "subject.v1", subject_descriptor_sha256: "a".repeat(64),
      fact_ids: ["fact.v1"], fact_sha256s: ["a".repeat(64)],
      evidence_ids: ["evidence.v1"], evidence_sha256s: ["a".repeat(64)],
    })).toThrow(/reviewed_at/);
  });

  it("rejects oversized arrays before record construction", () => {
    expect(() => fingerprintLegalDescriptorV1({
      ...MULTIBYTE_FACT,
      qualifiers: Array.from({ length: LEGAL_FINGERPRINT_MAX_ARRAY_ITEMS + 1 }, (_, index) => `q${index}`),
    })).toThrow(/item limit/);
  });

  it("rejects sparse arrays, array extra properties, and symbol-keyed descriptor fields", () => {
    const sparse = new Array<string>(1);
    expect(() => fingerprintLegalDescriptorV1({ ...MULTIBYTE_FACT, qualifiers: sparse })).toThrow(/sparse/);
    const extra = ["reviewed"];
    Object.defineProperty(extra, "extra", { value: "hidden", enumerable: true });
    expect(() => fingerprintLegalDescriptorV1({ ...MULTIBYTE_FACT, qualifiers: extra })).toThrow(/extra properties/);
    const symbol = Symbol("unknown");
    expect(() => fingerprintLegalDescriptorV1({ ...ASCII_ROUTE, [symbol]: "x" })).toThrow(/symbol/);
  });
});
